import java.util.*;
import java.math.BigInteger;

public class Main {
    static class ModInt {
        long val;
        int mod;

        public ModInt(long v, int m) {
            this.mod = m;
            this.val = v % m;
            if (this.val < 0) this.val += m;
        }

        public ModInt add(ModInt other) {
            long res = this.val + other.val;
            if (res >= mod) res -= mod;
            return new ModInt(res, mod);
        }

        public ModInt subtract(ModInt other) {
            long res = this.val - other.val;
            if (res < 0) res += mod;
            return new ModInt(res, mod);
        }

        public ModInt multiply(ModInt other) {
            long res = (this.val * other.val) % mod;
            return new ModInt(res, mod);
        }

        public long get() {
            return val;
        }
    }

    static class Pair {
        ModInt first, second;

        public Pair(ModInt f, ModInt s) {
            this.first = f;
            this.second = s;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        // Compute binomial coefficients C
        ModInt[][] C = new ModInt[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                C[i][j] = new ModInt(0, mod);
            }
        }
        C[0][0] = new ModInt(1, mod);
        for (int i = 1; i <= n; i++) {
            C[i][0] = new ModInt(1, mod);
            for (int j = 1; j <= i; j++) {
                C[i][j] = C[i - 1][j - 1].add(C[i - 1][j]);
            }
        }

        // Compute g array
        ModInt[] g = new ModInt[n + 1];
        for (int i = 0; i <= n; i++) {
            long val = (long) i * (i + 1) / 2;
            g[i] = new ModInt(val, mod);
        }

        // Compute f array
        Pair[] f = new Pair[n + 1];
        f[0] = new Pair(new ModInt(1, mod), new ModInt(0, mod));
        for (int i = 1; i <= n; i++) {
            ModInt sumFirst = new ModInt(0, mod);
            ModInt sumSecond = new ModInt(0, mod);
            for (int j = 0; j < i; j++) {
                ModInt z = f[j].first.multiply(f[i - 1 - j].first).multiply(C[i - 1][j]);
                sumFirst = sumFirst.add(z.multiply(new ModInt(i + 1, mod)));
                sumSecond = sumSecond.add(z.multiply(g[j].add(g[i - 1 - j])));
                ModInt term = (f[i - 1 - j].first.multiply(f[j].second).add(f[j].first.multiply(f[i - 1 - j].second)))
                        .multiply(C[i - 1][j]).multiply(new ModInt(i + 1, mod));
                sumSecond = sumSecond.add(term);
            }
            f[i] = new Pair(sumFirst, sumSecond);
        }

        // Initialize DP array
        Pair[][] dp = new Pair[n + 2][m + 1];
        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new Pair(new ModInt(0, mod), new ModInt(0, mod));
            }
        }
        dp[0][0] = new Pair(new ModInt(1, mod), new ModInt(0, mod));

        for (int l = 0; l <= n; l++) {
            for (int r = l + 1; r <= n + 1; r++) {
                int di = r - l - 1;
                for (int i = 0; i + di <= m; i++) {
                    ModInt z = dp[l][i].first.multiply(f[di].first);
                    dp[r][i + di].first = dp[r][i + di].first.add(z.multiply(C[i + di][di]));
                    ModInt secondPart = (dp[l][i].second.multiply(f[di].first))
                            .add(dp[l][i].first.multiply(f[di].second))
                            .multiply(C[i + di][di]);
                    dp[r][i + di].second = dp[r][i + di].second.add(secondPart);
                }
            }
        }

        System.out.println(dp[n + 1][m].second.get());
        sc.close();
    }
}

